def clean(df):
    df = df.copy()
    df['flipper_length_mm'] = df['flipper_length_mm'].abs()
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df['island'] = df['island'].str.strip().str.capitalize()
    return df

def answer(df):
    return df.groupby('species')['flipper_length_mm'].mean().to_dict()
